@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1543  cases=47
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-161
  @fn seedItems(h, takes, srcLen)  @ 177-182
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 184-193
  @fn trackList(trackCount)  @ 195-201
  @fn mapTracker(harness, inst, trackCount)  @ 205-219
      -- A tracker bound to the take 'i0' over a track list of the given width, with
      -- i0's placement as the caller states it; inst = nil binds it into no instance.

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 223-231
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 234-243
  @case 'focusState before any render returns both bits false'  [harness]  @ 246-253
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 259-272
  @case 'with no live instance, the new take mints a parked slot and selects it'  [harness]  @ 276-293
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 299-320
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 326-344
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 351-369
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 375-408
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 412-436
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 442-472
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 476-497
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 501-514
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 520-554
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 558-572
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 576-599
  @case 'a track step lands on the placement overlapping the current instance most'  [harness]  @ 603-639
  @case 'with nothing overlapping, a track step lands on the placement nearest in time'  [harness]  @ 643-678
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 685-702
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 706-729
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 733-756
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 760-795
  @case 'the walk steps along the track's placements in start order, holding at the ends'  [harness]  @ 799-847
  @case 'a walk into another slot resets the caret; within one slot the caret holds'  [harness]  @ 851-888
  @case 'deleting the instance drops that placement and lands on the one before it'  [harness]  @ 892-926
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 930-946
  @case 'the map window centres the bound column, and clamps it at both ends'  [harness]  @ 955-973
  @case 'the map window pages time, a start in the last bar opening the next page'  [harness]  @ 977-993
  @case 'with the tracker in no instance the map window pages on the edit cursor'  [harness]  @ 997-1004
  @case 'the map window carries the takes over it, the current instance marked'  [harness]  @ 1008-1019
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 1023-1050
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 1054-1078
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 1085-1106
  @case 'the play row and the head row count from the source origin, not the start'  [harness]  @ 1112-1136
  @case 'a dive carries the arrange QN to the caret row, and the caret hands it back'  [harness]  @ 1143-1162
  @case 'a caret outside the rendered span hands back the row the span stops at'  [harness]  @ 1166-1185
  @case 'leaving the tracker puts the arrange caret where the tracker caret is'  [harness]  @ 1189-1211
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 1217-1235
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 1239-1257
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 1261-1283
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 1287-1311
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 1317-1372
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 1380-1409
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 1415-1458
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1464-1478
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1485-1517
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1521-1541

